const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const elements=[
 {id:'paths',name:'Paths',color:'#b34f43',symbol:'━',definition:'The channels along which people move: streets, walks, transit lines and other routes. Repeated journeys organise the mental image of a city.',example:'Pennsylvania Avenue links the White House area and the Capitol; its diagonal course cuts across the street grid.'},
 {id:'edges',name:'Edges',color:'#395f72',symbol:'┄',definition:'Linear features perceived as boundaries between areas. An edge may interrupt movement, define a limit, or form a seam between neighbouring places.',example:'The Potomac shoreline makes a clear transition between built land and water. Bridges connect across that boundary.'},
 {id:'districts',name:'Districts',color:'#a17f34',symbol:'▧',definition:'Areas people recognise as having a common character and can mentally enter. Identity comes from a combination of form, activity and associations.',example:'Georgetown’s streets, rowhouses, canal and commercial corridors support a distinct local identity.'},
 {id:'nodes',name:'Nodes',color:'#bb622e',symbol:'◎',definition:'Strategic places where movement converges or activity concentrates. A junction becomes a node when it has significance in people’s experience.',example:'Dupont Circle combines the convergence of avenues with a recognisable public gathering space.'},
 {id:'landmarks',name:'Landmarks',color:'#426454',symbol:'▲',definition:'Distinctive external reference points that help people orient themselves. They may be visible from afar or familiar at a local scale.',example:'The Washington Monument’s isolated obelisk makes it a strong point of reference within the monumental core.'}
];
const refs=[
 ['Lynch, Kevin. The Image of the City.','MIT Press, 1960. Foundational text; five-element framework, especially chapter III.','https://mitpress.mit.edu/9780262620017/the-image-of-the-city/'],
 ['MIT · Images of the City','Institutional account of Lynch’s perception research and imageability.','https://betterworld.mit.edu/images-of-the-city/'],
 ['Library of Congress · Residence Act','Primary-document guide. Act of July 16, 1790; establishment of the permanent capital.','https://guides.loc.gov/residence-act'],
 ['Ellicott, Andrew; Hill, Samuel. Plan of the city of Washington.','1792. Library of Congress, Geography and Map Division, item 88694162. Historical comparison; user-supplied reproduction.','https://www.loc.gov/item/88694162/'],
 ['NPS · The Mall Cultural Landscape','2021. Planning history, landscape organisation and later implementation. Photographs: NPS / D. Weldon and NPS.','https://www.nps.gov/articles/600213.htm'],
 ['NPS · Make No Little Plans','L’Enfant and McMillan plans; development of the commemorative landscape.','https://www.nps.gov/nama/planyourvisit/make-no-little-plans.htm'],
 ['NPS · The Making of the Lincoln Memorial','The 1902 proposal and western terminus of the National Mall.','https://www.nps.gov/linc/learn/historyculture/the-making-of-the-lincoln-memorial.htm'],
 ['D.C. GIS · Roadway Block','Official roadway line geometry; downloaded October 13, 2026. Selected avenue overlays use street names.','https://maps2.dcgis.dc.gov/dcgis/rest/services/DCGIS_DATA/Transportation_WebMercator/MapServer/163'],
 ['D.C. GIS · Planimetrics 2023','Building footprints, layer 1; waterbodies, layer 14. Source geometry generalised for screen display.','https://maps2.dcgis.dc.gov/dcgis/rest/services/DCGIS_DATA/Planimetrics_2023/MapServer'],
 ['NPS · Dupont Circle','Public gathering space at the convergence of Massachusetts, Connecticut and New Hampshire avenues.','https://www.nps.gov/places/dupont-circle.htm'],
 ['NPS · Georgetown Historic District','National Register record, 1967. Historic fabric and district geography.','https://npgallery.nps.gov/AssetDetail/ccf49801-c659-4575-a8c0-585bfa90443d'],
 ['NPS · Capitol Hill Historic District','National Register documentation, boundary extension, 2008.','https://npgallery.nps.gov/GetAsset/b5ec7d19-4b87-458c-9f47-77189fdf7a7b'],
 ['NPS · Construction History of Union Station','Historic structure study, 1969. Station as a gateway and transport convergence.','https://irmadev.nps.gov/DataStore/Reference/Profile/2279580'],
 ['NPS · Rock Creek Park','Landscape corridor and park context.','https://www.nps.gov/rocr/index.htm'],
 ['Architect of the Capitol · U.S. Capitol','Architectural reference for the Capitol and dome.','https://www.aoc.gov/explore-capitol-campus/buildings-grounds/capitol-building'],
 ['NPS · Washington Monument','Architectural and historical reference.','https://www.nps.gov/wamo/index.htm']
];
const cite=(...ids)=>`<p class="source-note">Sources / ${ids.map(i=>`<a href="${refs[i][2]}" target="_blank" rel="noopener">${refs[i][0]}</a>`).join(' · ')}</p>`;
const takeaway=t=>`<div class="takeaway"><b>THE PLANNING OBSERVATION</b>${t}</div>`;
const image=(src,alt,caption)=>`<figure class="visual"><img src="assets/${src}" alt="${alt}" loading="lazy"><figcaption>${caption}</figcaption></figure>`;
const mapSlot=(layers,labels=true)=>`<div class="map-frame" data-layers="${layers}" data-labels="${labels}"><img src="assets/network.svg" alt="Washington street-network fallback"><div class="north" aria-label="North is up">↑<br>N</div><div class="scale"><span></span>1 km</div><div class="map-tools"><button data-zoom="in" aria-label="Zoom map in">+</button><button data-zoom="out" aria-label="Zoom map out">−</button><button data-zoom="reset" aria-label="Reset map zoom">↺</button></div></div>`;
const key=ids=>`<div class="map-key">${elements.filter(e=>ids.includes(e.id)).map(e=>`<span style="--c:${e.color}">${e.symbol} ${e.name}</span>`).join('')}</div>`;
const diagram=i=>{let x=['<path d="M20 68L180 22" stroke-width="7"/><path d="M50 15V85M95 15V85M145 15V85M15 40H185M15 65H185" stroke-width="1" opacity=".35"/>','<path d="M20 65Q70 0 100 50T185 35" stroke-width="8" fill="none"/><path d="M20 78Q70 13 100 63T185 48" stroke-width="1.5" stroke-dasharray="4 4"/>','<path d="M35 10L165 20L180 85L30 80Z" fill="currentColor" fill-opacity=".2" stroke-dasharray="4 4"/><path d="M55 35H80V65H55ZM100 35H145V65H100Z" fill="currentColor" stroke="none"/>','<path d="M10 50H190M100 5V95M20 10L180 90M20 90L180 10" stroke-width="2"/><circle cx="100" cy="50" r="20" fill="var(--paper)" stroke-width="4"/>','<path d="M20 83H180M90 80V27L100 7L110 27V80Z" stroke-width="2"/><path d="M15 55H60M140 55H185" stroke-width="1" opacity=".4"/>'][i];return `<svg viewBox="0 0 200 100" aria-label="Conceptual ${elements[i].name.toLowerCase()} diagram" role="img" style="color:${elements[i].color}" fill="none" stroke="currentColor">${x}</svg>`};
const plates=()=>`<div class="plate-grid">${[
 ['Washington Monument','<path d="M120 140V37L132 10L144 37V140Z"/><path d="M40 144H224"/>','The obelisk: a singular vertical reference in an open landscape. Its form is recognisable without entering it.'],
 ['U.S. Capitol','<path d="M20 140V100H80V85H184V100H245V140ZM107 85V65Q132 15 157 65V85M102 65H162M125 35V23H139V35M20 120H245M45 105V140M65 105V140M200 105V140M220 105V140"/>','The dome: a civic landmark and eastern anchor of the Mall. It is also part of a working legislative complex.'],
 ['Lincoln Memorial','<path d="M30 140H234V135H30ZM42 130V70H222V130M35 65L132 38L230 65ZM40 65H225M60 78V127M85 78V127M110 78V127M135 78V127M160 78V127M185 78V127M208 78V127"/>','The temple form: a broad, low terminus to the Mall’s western vista, made distinct by its setting.']
 ].map(([n,s,t])=>`<div class="plate"><svg viewBox="0 0 265 160" fill="none" stroke="var(--green)" stroke-width="2" role="img" aria-label="${n} simplified silhouette">${s}</svg><div><h3>${n}</h3><p>${t}</p></div></div>`).join('')}</div><p class="caption">Analytical silhouettes, not measured elevations. Relative drawing sizes do not represent relative building heights.</p>`;
const timeline=`<div class="timeline"><div><b>1790</b><p>The Residence Act establishes a permanent federal seat on the Potomac.</p></div><div><b>1791</b><p>L’Enfant develops the federal city plan: grid, avenues, public spaces and civic sites.</p></div><div><b>1792–1800</b><p>Ellicott’s plan is published in 1792; the federal government moves to Washington in 1800.</p></div><div><b>1851 → 1902</b><p>Downing’s landscape proposal precedes the McMillan Commission’s return to formal axes.</p></div><div><b>Today</b><p>The historic core sits within a much larger, evolving city of neighbourhoods and infrastructure.</p></div></div>`;
const chapters=[
 {title:'Why do we read cities?',short:'Perception',question:'01 / THE CITY IN YOUR MIND',deck:'A city is more than buildings and roads. It is a system of spaces, movements, boundaries, identities and memories.',visual:image('mall-panorama.jpg','View west along the National Mall toward the Washington Monument','Documented photograph / The National Mall, looking west. NPS / D. Weldon.'),body:`<h3>We navigate with more than a map.</h3><p>A familiar route, an unmistakable tower, the moment a street opens into a square: these cues help us locate ourselves and anticipate what comes next.</p><p>A mental map is the selective picture a person forms through experience. Different people remember different cities—even when walking the same streets.</p>`,extra:`<div class="composition"><div class="demo"><div class="mode-switch"><button data-demo="confusing" aria-pressed="true">Few orientation cues</button><button data-demo="legible" aria-pressed="false">Add recognisable cues</button></div><svg id="mental-demo" viewBox="0 0 600 260" role="img" aria-label="Conceptual comparison of orientation cues"></svg><p class="caption">Conceptual teaching diagram / The same street network, with and without a highlighted route, district and landmark. Not a Washington map or a measured test of legibility.</p></div><div class="annotation"><h3>What makes a city easy to read?</h3><p>Switch on the cues. The street network stays the same; the information available to the traveller changes.</p><p>This explains why legibility involves perception as well as geometry.</p></div></div>`,take:'Useful urban cues allow people to recognise where they are and connect one place with another.',sources:[0,1]},
 {title:'The image of the city',short:'Lynch',question:'02 / A FRAMEWORK FOR SEEING',deck:'Kevin Lynch’s 1960 study offers five ways to describe the elements people use to recognise and organise urban environments.',visual:`<div class="element-tabs">${elements.map((e,i)=>`<button data-element="${i}" aria-pressed="${i===0}">${diagram(i)}<small>0${i+1}</small><b>${e.name}</b></button>`).join('')}</div><div class="definition" aria-live="polite"><h3 id="element-name">Paths</h3><div><p id="element-definition">${elements[0].definition}</p><p id="element-example" class="caption">${elements[0].example}</p></div></div>`,body:`<h3>Legibility & imageability</h3><p><b>Legibility</b> describes how readily a place’s parts can be recognised and organised into a coherent pattern.</p><p><b>Imageability</b> describes the capacity of physical form to evoke a strong mental image.</p><p>The five elements work together. An avenue may be a path, the edge of a district, and the approach to a landmark.</p>`,take:'Lynch provides a lens for analysis—not five mandatory rules that L’Enfant used to design Washington.',sources:[0,1]},
 {title:'A planned capital',short:'History',question:'03 / INTENTION & TRANSFORMATION',deck:'Washington’s monumental core grew from a planned framework, but the city visible today is the product of many later changes.',visual:`<div class="history-pair"><figure><img src="assets/historical-reference.png" alt="User-supplied reproduction of the 1792 published Washington plan"><figcaption>Historical document / 1792 Ellicott plan, following L’Enfant’s 1791 design. User-supplied reproduction; Library of Congress catalog reference.</figcaption></figure><figure>${mapSlot('paths,landmarks')}<figcaption>Contemporary GIS / Selected part of the core, north up. Comparable orientation; different extents. These maps are not georectified or a precise overlay.</figcaption></figure></div>`,body:`<h3>One framework, many authors.</h3><p>L’Enfant combined a street grid with diagonal avenues and prominent civic sites. Ellicott revised and published the plan in 1792.</p><p>The 1901–1902 Senate Park Commission, commonly called the McMillan Commission, reasserted a formal Mall landscape and proposed its western extension toward a Lincoln memorial.</p><p>Later implementation, reclaimed land and changing uses separate the original proposal from the present city.</p>`,extra:timeline,take:'Read the historic plan as an intention, then examine how later decisions transformed it.',sources:[2,3,4,5,6]},
 {title:'The anatomy of the plan',short:'Urban form',question:'04 / GRID + DIAGONAL + LANDSCAPE',deck:'The orthogonal grid makes local connections. Diagonal avenues establish longer relationships between significant places.',visual:mapSlot('paths,landmarks'),body:`<h3>Two networks, one city.</h3><p>The repeated grid supports a fine-grained street pattern. Diagonals cross that pattern, opening longer routes and producing distinctive junctions.</p><p>The Mall is a civic landscape, not simply another street. Its east–west composition gives the monumental core a recognisable spatial order.</p><p>Rivers and landscape corridors interrupt the fabric. Georgetown predates the federal city plan and has a different history.</p>`,extra:`<div class="composition"><div class="demo"><svg viewBox="0 0 600 220" role="img" aria-label="Conceptual grid and diagonal relationship"><defs><pattern id="grid-demo" width="50" height="40" patternUnits="userSpaceOnUse"><path d="M50 0H0V40" fill="none" stroke="#a8aca1" stroke-width="1"/></pattern></defs><rect x="20" y="20" width="560" height="180" fill="url(#grid-demo)"/><path d="M30 190L550 35" stroke="#b34f43" stroke-width="7"/><circle cx="280" cy="115" r="16" fill="#f5f3ed" stroke="#bb622e" stroke-width="3"/></svg><p class="caption">Conceptual diagram / A diagonal cuts a regular grid; an important junction can become a node.</p></div><div class="annotation"><h3>Order is relational.</h3><p>The plan’s power lies in connections between routes, public spaces and civic buildings.</p></div></div>`,take:'Urban structure becomes readable when movement and focal places reinforce each other.',sources:[3,4,5,7,8]},
 {title:'Paths / the moving city',short:'Paths',question:'05 / HOW DO PEOPLE MOVE?',deck:'Paths structure the sequence of places we experience. The route is both a connection and a way of learning the city.',visual:mapSlot('paths,landmarks'),body:`<div class="examples">${['Pennsylvania Avenue','Massachusetts Avenue','Connecticut Avenue','National Mall'].map((n,i)=>`<button data-path="${i}" aria-pressed="${i===0}">${n}</button>`).join('')}</div><div id="path-info" aria-live="polite"><h3>Pennsylvania Avenue</h3><p>A diagonal civic connection between the White House area and the Capitol. Its relation to the grid gives movement a distinctive direction.</p></div><p>The National Mall operates as a pedestrian landscape and a setting for events. It should not be read as equivalent to a vehicular avenue.</p>`,take:'A route is legible when direction, continuity and memorable destinations can be understood together.',sources:[0,4,7]},
 {title:'Edges / the limits of the city',short:'Edges',question:'06 / WHAT SEPARATES OR DEFINES?',deck:'Some of the strongest boundaries in Washington are landscapes rather than lines on an administrative map.',visual:mapSlot('edges'),body:`<div class="examples"><button data-edge="Potomac shoreline">Potomac River</button><button data-edge="Rock Creek corridor">Rock Creek corridor</button></div><div id="edge-info" aria-live="polite"><h3>Water and landscape as boundaries.</h3><p>The Potomac distinguishes the city’s land from a broad water surface. Its shoreline can support orientation, while bridges provide crossings.</p><p>Rock Creek’s valley and park corridor can separate adjacent urban fabrics. At crossings and trails, the same landscape also connects places.</p></div><p>Not every street or jurisdiction line is a strong perceived edge. These examples are analytical interpretations, not findings from a resident survey.</p>`,take:'An edge can be a barrier, a visual limit, or a seam. Its meaning depends on how people use and cross it.',sources:[0,8,13]},
 {title:'Districts / distinct urban identities',short:'Districts',question:'07 / WHAT MAKES A PLACE RECOGNISABLE?',deck:'District identity comes from recurring patterns of architecture, use, streets and public life—not a boundary alone.',visual:mapSlot('districts'),body:`<div class="examples">${['Georgetown','Capitol Hill','Downtown'].map(n=>`<button data-district="${n}">${n}</button>`).join('')}</div><div id="district-info" aria-live="polite"><h3>Georgetown</h3><p>A historic fabric of rowhouses, commercial streets and the canal landscape. Its identity is different from the monumental federal core.</p></div><p class="caption">Dashed outlines are approximate interpretive study areas. They are not official historic-district boundaries and do not assert a universal mental map.</p>`,extra:`<div class="plate-grid"><div class="plate">${image('georgetown.jpg','Old Stone House in Georgetown','Documented photograph / NPS / Jordan Land.')}<h3>Georgetown</h3><p>Historic small-scale buildings, a canal corridor and busy local streets create a recognisable texture.</p></div><div class="plate">${image('capitol.jpg','United States Capitol','Documented photograph / NPS / Mike Litterst.')}<h3>Capitol Hill</h3><p>Residential streets and civic buildings produce related but different images within the wider neighbourhood.</p></div><div class="plate">${image('mall-street.jpg','Museum frontage beside the National Mall','Documented photograph / NPS.')}<h3>Downtown & civic frontage</h3><p>Commercial and institutional buildings define larger street spaces. The pictured Mall frontage is a comparison, not a representative image of all Downtown.</p></div></div>`,take:'A district becomes recognisable through the continuity of its character, while its perceived limits may remain flexible.',sources:[0,10,11,8]},
 {title:'Nodes / places of convergence',short:'Nodes',question:'08 / WHERE DOES ACTIVITY CONCENTRATE?',deck:'A node is a place of significance along a journey: a meeting point, interchange, civic space or concentration of activity.',visual:mapSlot('nodes,paths'),body:`<div class="examples">${['Dupont Circle','Logan Circle','Union Station'].map(n=>`<button data-node="${n}">${n}</button>`).join('')}</div><div id="node-info" aria-live="polite"><h3>Dupont Circle</h3><p>Massachusetts, Connecticut and New Hampshire avenues converge around a distinctive public space. Movement and gathering reinforce its identity.</p></div><p>A simple intersection is not automatically a significant node. Concentration of activity and importance in a person’s journey matter.</p>`,extra:`<div class="composition"><div class="map-frame" id="dupont-detail" data-layers="nodes,paths" data-labels="false"></div><div class="annotation"><h3>Read the convergence.</h3><p>This enlarged view uses the actual roadway geometry around Dupont Circle. The ring marker identifies the public-space node; it is not a surveyed circle boundary.</p><p class="caption">Documented road geometry / D.C. GIS. Analytical marker.</p></div></div>`,take:'A memorable node joins movement with a reason to arrive, pause, transfer or meet.',sources:[0,9,12,7]},
 {title:'Landmarks / points of recognition',short:'Landmarks',question:'09 / WHAT DO WE REMEMBER?',deck:'Distinctive objects help people locate themselves in relation to the city. Their setting matters as much as their form.',visual:mapSlot('landmarks'),body:`<div class="examples">${['Washington Monument','U.S. Capitol','Lincoln Memorial'].map(n=>`<button data-landmark="${n}">${n}</button>`).join('')}</div><div id="landmark-info" aria-live="polite"><h3>Washington Monument</h3><p>An isolated obelisk within the open monumental landscape. Its vertical form can orient a visitor, although visibility varies by location, trees and buildings.</p></div><p>The Capitol and Lincoln Memorial anchor the Mall’s composition. Map relationships shown here are not measured sightlines or a viewshed analysis.</p>`,extra:plates(),take:'Landmarks become useful references through distinctive form, meaningful associations and a readable spatial setting.',sources:[0,4,6,14,15]},
 {title:'The complete urban image',short:'Synthesis',question:'10 / FIVE ELEMENTS, ONE SYSTEM',deck:'Turn layers on and off. Compare two elements. Select an example to see how routes, boundaries, identities and focal places support one another.',visual:`<div class="layer-controls">${elements.map(e=>`<label style="--c:${e.color}"><input type="checkbox" data-layer="${e.id}" checked>${e.symbol} ${e.name}</label>`).join('')}</div>${mapSlot('paths,edges,districts,nodes,landmarks')}<div class="compare-controls"><span>Compare</span><select id="compare-a" aria-label="First element">${elements.map(e=>`<option value="${e.id}">${e.name}</option>`).join('')}</select><span>with</span><select id="compare-b" aria-label="Second element">${elements.map(e=>`<option value="${e.id}" ${e.id==='nodes'?'selected':''}>${e.name}</option>`).join('')}</select><button id="compare">Apply pair</button><button id="reset-layers">Show all / reset</button></div>`,body:`<div id="map-info" aria-live="polite"><h3>Select a mapped example.</h3><p>The avenue is a path; its intersection may be a node; a nearby monument becomes a landmark. The experience is a relationship, not five separate lists.</p></div>${key(elements.map(e=>e.id))}<details><summary>How to read this map</summary><p>Roads, water and footprints use official D.C. GIS geometry. Route overlays follow selected named roadway segments. District polygons are approximate study regions. Node rings and landmark triangles are location symbols. They do not indicate surveyed footprints or measured visibility. Pan by dragging; use + / − to zoom. Keyboard users can focus examples and press Enter.</p></details>`,take:'The image of the city emerges from the overlap of multiple elements—and changes with the observer.',sources:[0,7,8]},
 {title:'What can we learn?',short:'Lessons',question:'11 / FROM READING TO DESIGN',deck:'Visual clarity is a useful quality of urban form, but it is only one part of the experience of a city.',visual:`<ol class="lesson-list"><li>Connect movement networks to recognisable destinations.</li><li>Give public spaces a meaningful relationship to routes.</li><li>Protect spatial identities without assuming that every user perceives them alike.</li><li>Read landscape boundaries as both limits and opportunities for connection.</li><li>Consider streets, districts and landmarks together.</li></ol>`,body:`<h3>Order is not the whole story.</h3><p>A long avenue may be easy to recognise while still being difficult to cross. A monumental space may be memorable while leaving some everyday needs unmet.</p><p>Evaluate accessibility, inclusion, shade, safety and pedestrian comfort alongside visual legibility.</p>`,extra:`<p class="critical">A visually ordered city is not automatically an equally accessible, inclusive, or pedestrian-friendly city.</p><p class="conclusion">Urban planning shapes the physical city. Imageability helps explain how people understand and remember it.</p>`,take:'Use imageability as one analytical tool within a broader assessment of urban life.',sources:[0,1]},
 {title:'References & credits',short:'Sources',question:'12 / THE EVIDENCE BEHIND THE ATLAS',deck:'The study separates documented geography, analytical interpretation and conceptual teaching diagrams.',visual:`<ul class="ref-list">${refs.map(([t,d,u])=>`<li><a href="${u}" target="_blank" rel="noopener">${t} ↗</a><span>${d}</span></li>`).join('')}</ul>`,body:`<h3>Drawing & image credits</h3><p>All analytical SVG diagrams and silhouettes were created for this atlas. Base geometry: District of Columbia Office of the Chief Technology Officer / D.C. GIS. The data snapshot is not a guarantee of current on-site conditions.</p><p>Photo credits: Mall — NPS / D. Weldon; <a href="https://home.nps.gov/places/old-stone-house.htm">Old Stone House — NPS / Jordan Land</a>; <a href="https://www.nps.gov/places/us-capitol.htm">Capitol — NPS / Mike Litterst</a>; museum frontage — NPS. Supplied reference images inform the graphic direction.</p><p>Historical and contemporary images are compared without claiming exact alignment. Study regions and element classifications are the atlas author’s interpretation.</p>`,take:'Follow the source links to investigate the evidence and distinguish it from the atlas’s interpretation.',sources:[]}
];
$('#chapters').innerHTML=chapters.map((c,i)=>`<a href="#chapter-${i+1}"><b>${String(i+1).padStart(2,'0')}</b>${c.short}</a>`).join('');
$('#chapter-content').innerHTML=chapters.map((c,i)=>`<article id="chapter-${i+1}"><div class="chapter-head"><div class="chapter-number">${String(i+1).padStart(2,'0')}</div><div><div class="question">${c.question}</div><h2>${c.title}</h2><p>${c.deck}</p></div></div><div class="composition"><div>${c.visual}</div><div class="annotation">${c.body}</div></div>${c.extra||''}${takeaway(c.take)}${cite(...c.sources)}</article>`).join('');
const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){$$('#chapters a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id));}})},{rootMargin:'-15% 0px -65% 0px'});$$('article').forEach(a=>observer.observe(a));
$$('[data-element]').forEach(b=>b.onclick=()=>{const e=elements[+b.dataset.element];$$('[data-element]').forEach(x=>x.setAttribute('aria-pressed',x===b));$('#element-name').textContent=e.name;$('#element-name').style.color=e.color;$('#element-definition').textContent=e.definition;$('#element-example').textContent=e.example;});
function demo(legible){let s='';for(let x=40;x<580;x+=65)s+=`<path d="M${x} 25V235"/>`;for(let y=40;y<245;y+=50)s+=`<path d="M25 ${y}H575"/>`;s+=`<path d="M25 235L400 25M100 235L575 65"/>`;$('#mental-demo').innerHTML=`<g fill="none" stroke="#999d91" stroke-width="2">${s}</g>${legible?'<path d="M105 25V190H495" fill="none" stroke="#b34f43" stroke-width="7"/><rect x="300" y="40" width="170" height="100" fill="#a17f3433" stroke="#a17f34" stroke-dasharray="5 4"/><path d="M495 190L485 158L505 158Z" fill="#426454"/><text x="318" y="92" font-size="13" font-family="Montserrat">DISTRICT</text><text x="395" y="220" font-size="13" font-family="Montserrat">LANDMARK</text>':''}`;}
demo(false);$$('[data-demo]').forEach(b=>b.onclick=()=>{$$('[data-demo]').forEach(x=>x.setAttribute('aria-pressed',x===b));demo(b.dataset.demo==='legible');});
let mapData;const maps=[];const NS='http://www.w3.org/2000/svg';
const coords={ 'Dupont Circle':[-77.0434,38.9096], 'Logan Circle':[-77.0296,38.9096], 'Union Station':[-77.0064,38.897], 'Washington Monument':[-77.0353,38.8895], 'U.S. Capitol':[-77.0091,38.8899], 'Lincoln Memorial':[-77.0502,38.8893] };
const notes={
 'Pennsylvania Avenue':'The selected roadway segments show a diagonal route through the federal core. Between the White House area and Capitol, route and civic identity reinforce one another.',
 'Massachusetts Avenue':'A diagonal route crossing the northwest grid and linking distinctive circles and civic places. The highlighted segments are actual named roadway geometry.',
 'Connecticut Avenue':'A northwest corridor passing through Dupont Circle. It acts as both a movement route and a sequence of recognisable places.',
 'National Mall':'An open pedestrian and civic landscape. The displayed axis is a schematic relationship between the Lincoln Memorial and Capitol, not a mapped walking itinerary.',
 'Potomac shoreline':'The water–land transition offers a strong physical and visual limit. Crossings and waterfront spaces can connect across and along it.',
 'Rock Creek corridor':'A wooded valley separating some urban fabrics while trails and crossings connect them. The dashed line is a simplified corridor centre, not the park boundary.',
 'Georgetown':'Historic small-scale buildings, commercial corridors and canal landscape contribute to a distinct identity. The dashed polygon is an approximate study area.',
 'Capitol Hill':'Residential rowhouse fabric and the proximity of major civic institutions give the area overlapping everyday and national identities. The polygon is interpretive.',
 'Downtown':'Commercial and institutional uses and larger building volumes support an identifiable central area. Its perceived extent varies with the observer.',
 'Dupont Circle':'Avenues converge around a public gathering space. Its identity combines a movement junction with social use; the ring is a location symbol.',
 'Logan Circle':'A distinctive circular public space in a surrounding residential fabric. Its geometry and setting provide a local reference and gathering place.',
 'Union Station':'A transport gateway and interchange where journeys converge. The building can also act as a landmark, demonstrating overlap between elements.',
 'Washington Monument':'An isolated obelisk in the monumental landscape. Its distinctive vertical form supports orientation; no measured visibility is asserted.',
 'U.S. Capitol':'The dome and civic setting create an eastern reference for the Mall. Its significance involves form, position and symbolic associations.',
 'Lincoln Memorial':'A temple-like building at the western end of the Mall. Its setting reinforces its role as a visual and symbolic terminus.'
};
function point(p){const b=mapData.bbox;return [(p[0]-b[0])/(b[2]-b[0])*1000,(b[3]-p[1])/(b[2]-b[0])*720];}
function poly(c){return c.map(p=>point(p).join(',')).join(' ');}
function marker(name,type){const [x,y]=point(coords[name]);const shape=type==='nodes'?`<circle cx="${x}" cy="${y}" r="10" class="node"/>`:`<path d="M${x} ${y-10}l-9 17h18Z" class="landmark"/>`;return `<g data-example="${name}" tabindex="0" role="button" aria-label="${name}" class="example">${shape}<title>${name}</title></g>`;}
function overlays(){return `<g data-group="districts">${[
 ['Georgetown',[[-77.078,38.916],[-77.054,38.916],[-77.052,38.902],[-77.067,38.902],[-77.078,38.906]]],
 ['Capitol Hill',[[-77.009,38.901],[-76.996,38.901],[-76.996,38.879],[-77.012,38.879]]],
 ['Downtown',[[-77.043,38.908],[-77.019,38.908],[-77.019,38.897],[-77.043,38.897]]]
 ].map(([n,c])=>`<polygon points="${poly(c)}" class="district" data-example="${n}" tabindex="0" role="button" aria-label="${n} approximate district"><title>${n}</title></polygon>`).join('')}</g><g data-group="edges"><use href="#water-lines" class="edge" data-example="Potomac shoreline" tabindex="0" role="button" aria-label="Waterbody shorelines including the Potomac"/><polyline points="${poly([[-77.0538,38.922],[-77.0509,38.916],[-77.0522,38.911],[-77.0527,38.908],[-77.056,38.902],[-77.057,38.898]])}" class="edge" data-example="Rock Creek corridor" tabindex="0" role="button" aria-label="Rock Creek corridor, schematic"/></g><g data-group="paths">${Object.entries(mapData.routes).map(([n,p])=>`<path d="${p}" class="route" data-example="${n[0]+n.slice(1).toLowerCase()} Avenue" tabindex="0" role="button" aria-label="${n} Avenue"/>`).join('')}<polyline class="route" stroke-dasharray="8 4" points="${poly([coords['Lincoln Memorial'],coords['Washington Monument'],coords['U.S. Capitol']])}" data-example="National Mall" tabindex="0" role="button" aria-label="National Mall schematic axis"/></g><g data-group="nodes">${['Dupont Circle','Logan Circle','Union Station'].map(n=>marker(n,'nodes')).join('')}</g><g data-group="landmarks">${['Washington Monument','U.S. Capitol','Lincoln Memorial'].map(n=>marker(n,'landmarks')).join('')}</g>`;}
function mapLabels(layers){return `<g class="labels">${Object.entries(coords).filter(([n])=>layers.includes(n.includes('Circle')||n==='Union Station'?'nodes':'landmarks')).map(([n,c])=>{const [x,y]=point(c);return `<text x="${x+14}" y="${y+(n==='Logan Circle'?22:-12)}">${n}</text>`}).join('')}</g>`;}
function makeMap(frame){const layers=frame.dataset.layers.split(',');const svg=document.createElementNS(NS,'svg');svg.setAttribute('viewBox','0 0 1000 720');svg.setAttribute('class','atlas-map');svg.setAttribute('aria-label','Washington, D.C. interactive analytical map');svg.innerHTML=`<rect width="1000" height="720" fill="#eeeee6"/><use href="#water-lines" class="water"/><use href="#building-lines" class="buildings"/><use href="#road-lines" class="roads"/>${overlays()}${frame.dataset.labels==='false'?'':mapLabels(layers)}`;frame.querySelector('img')?.remove();frame.prepend(svg);svg.querySelectorAll('[data-group]').forEach(g=>g.style.display=layers.includes(g.dataset.group)?'':'none');const m={frame,svg,view:[0,0,1000,720],layers};maps.push(m);svg.querySelectorAll('[data-example]').forEach(t=>{t.onclick=e=>{e.stopPropagation();showExample(t.dataset.example,frame);};t.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showExample(t.dataset.example,frame);}};});frame.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>zoom(m,b.dataset.zoom));let drag;svg.addEventListener('pointerdown',e=>{if(e.target.closest('[data-example]'))return;drag={x:e.clientX,y:e.clientY,v:[...m.view]};svg.setPointerCapture(e.pointerId);});svg.addEventListener('pointermove',e=>{if(!drag)return;const r=svg.getBoundingClientRect();m.view=[drag.v[0]-(e.clientX-drag.x)/r.width*drag.v[2],drag.v[1]-(e.clientY-drag.y)/r.height*drag.v[3],drag.v[2],drag.v[3]];updateView(m);});svg.addEventListener('pointerup',()=>drag=null);svg.addEventListener('pointercancel',()=>drag=null);if(frame.id==='dupont-detail'){const [x,y]=point(coords['Dupont Circle']);m.view=[x-110,y-80,220,160];updateView(m);}return m;}
function updateView(m){m.svg.setAttribute('viewBox',m.view.join(' '));const scale=m.frame.querySelector('.scale');if(scale)scale.style.display=m.view[2]===1000?'':'none';}
function zoom(m,dir){if(dir==='reset'){m.view=[0,0,1000,720];updateView(m);return;}const f=dir==='in'?.75:1.333333;const [x,y,w,h]=m.view;const nw=Math.min(1500,Math.max(160,w*f));const nh=nw*.72;m.view=[x+(w-nw)/2,y+(h-nh)/2,nw,nh];updateView(m);}
function showExample(name,frame){const article=frame.closest('article');const panel=article?.querySelector('#map-info,#path-info,#edge-info,#district-info,#node-info,#landmark-info');if(panel)panel.innerHTML=`<h3>${name}</h3><p>${notes[name]||'An interpretive example of a perceived urban element.'}</p>`;$('#status').textContent=name+': '+(notes[name]||'');}
async function initialiseMaps(){try{const r=await fetch('assets/map-data.json');if(!r.ok)throw new Error('Map data unavailable');mapData=await r.json();const defs=document.createElementNS(NS,'svg');defs.setAttribute('width','0');defs.setAttribute('height','0');defs.style.position='absolute';defs.setAttribute('aria-hidden','true');defs.innerHTML=`<defs><path id="road-lines" d="${mapData.roads}"/><path id="building-lines" d="${mapData.buildings}" fill-rule="evenodd"/><path id="water-lines" d="${mapData.water}"/></defs>`;document.body.prepend(defs);$$('.map-frame').forEach(makeMap);window.mapsReady=true;}catch(e){$$('.map-tools').forEach(t=>t.remove());$('#status').textContent='Interactive map unavailable. Static maps remain visible.';console.error(e);}}
initialiseMaps();
const setPanel=(id,n)=>$(id).innerHTML=`<h3>${n}</h3><p>${notes[n]}</p>`;
$$('[data-path]').forEach(b=>b.onclick=()=>{const n=['Pennsylvania Avenue','Massachusetts Avenue','Connecticut Avenue','National Mall'][+b.dataset.path];setPanel('#path-info',n);$$('[data-path]').forEach(x=>x.setAttribute('aria-pressed',x===b));const m=maps.find(m=>m.frame.closest('#chapter-5'));m?.svg.querySelectorAll('.route').forEach(p=>p.style.opacity=p.dataset.example===n?'1':'.18');});
$$('[data-edge]').forEach(b=>b.onclick=()=>setPanel('#edge-info',b.dataset.edge));$$('[data-district]').forEach(b=>b.onclick=()=>setPanel('#district-info',b.dataset.district));$$('[data-node]').forEach(b=>b.onclick=()=>setPanel('#node-info',b.dataset.node));$$('[data-landmark]').forEach(b=>b.onclick=()=>setPanel('#landmark-info',b.dataset.landmark));
function applyLayers(){const m=maps.find(m=>m.frame.closest('#chapter-10'));if(!m)return;m.layers=$$('[data-layer]:checked').map(x=>x.dataset.layer);m.svg.querySelectorAll('[data-group]').forEach(g=>{const on=m.layers.includes(g.dataset.group);g.style.display=on?'':'none';g.querySelectorAll('[tabindex]').forEach(t=>t.setAttribute('tabindex',on?'0':'-1'));});m.svg.querySelector('.labels')?.remove();m.svg.insertAdjacentHTML('beforeend',mapLabels(m.layers));}
$$('[data-layer]').forEach(x=>x.onchange=applyLayers);$('#compare').onclick=()=>{const pair=[$('#compare-a').value,$('#compare-b').value];$$('[data-layer]').forEach(x=>x.checked=pair.includes(x.dataset.layer));applyLayers();$('#map-info').innerHTML=`<h3>${pair.map(id=>elements.find(e=>e.id===id).name).filter((v,i,a)=>a.indexOf(v)===i).join(' + ')}</h3><p>Follow where the selected elements overlap. Select a mapped example to examine its role.</p>`;};$('#reset-layers').onclick=()=>{$$('[data-layer]').forEach(x=>x.checked=true);applyLayers();const m=maps.find(m=>m.frame.closest('#chapter-10'));if(m)zoom(m,'reset');$('#map-info').innerHTML='<h3>All five elements.</h3><p>Select a mapped example to examine how it contributes to the urban image.</p>';};
$('#present').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{$('#status').textContent='Fullscreen is unavailable in this browser.';}};document.addEventListener('fullscreenchange',()=>{$('#present').textContent=document.fullscreenElement?'↙ Exit presentation':'↗ Present';});document.addEventListener('keydown',e=>{if(!document.fullscreenElement||e.target.matches('input,select,button'))return;if(['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();const a=$$('#chapters a');const i=Math.max(0,a.findIndex(a=>a.classList.contains('active')));a[Math.min(11,Math.max(0,i+(e.key==='ArrowRight'?1:-1)))].click();}});
$('#print-open').onclick=()=>$('#print-dialog').showModal();$('#print-dialog .close').onclick=()=>$('#print-dialog').close();
function printVisual(c,i){if(i===1)return elements.map((e,j)=>`<div style="display:grid;grid-template-columns:40mm 1fr;align-items:center;margin-bottom:3mm">${diagram(j)}<p style="font-size:9pt"><b>${e.name}</b><br>${e.definition}</p></div>`).join('');if(i===11)return c.visual;const source=$(`#chapter-${i+1} .composition>div:first-child`).cloneNode(true);source.querySelectorAll('.layer-controls,.compare-controls,.map-tools').forEach(t=>t.remove());source.querySelectorAll('[id]').forEach(t=>t.removeAttribute('id'));source.querySelectorAll('svg.atlas-map').forEach(s=>{s.setAttribute('viewBox','0 0 1000 720');s.querySelectorAll('[data-group]').forEach(g=>g.style.display=g.closest('.map-frame').dataset.layers.split(',').includes(g.dataset.group)?'':'none');s.querySelectorAll('.route').forEach(p=>p.style.opacity='1');});return source.innerHTML;}
function buildPrint(orientation){const target=$('#print-edition');target.innerHTML=chapters.map((c,i)=>{let body=c.body;if(i===0)body+=`<p><b>Mental-map exercise:</b> Compare the same route before and after identifying a distinctive destination. The cues alter orientation without changing the physical network.</p>`;if(i===2)body+=`<div class="print-timeline"><p><b>1790</b> Residence Act: permanent capital on the Potomac.</p><p><b>1791</b> L’Enfant: grid, avenues and civic sites.</p><p><b>1792 / 1800</b> Published Ellicott plan / government moves to Washington.</p><p><b>1851 / 1901–02</b> Downing landscape / McMillan formal composition.</p><p><b>Today</b> A larger city surrounding the historic core.</p></div>`;if(i===8)body+=plates();if(i===10)body+=c.extra;const clean=document.createElement('div');clean.innerHTML=body;clean.querySelectorAll('.examples,details,button').forEach(e=>e.remove());clean.querySelectorAll('[id]').forEach(e=>e.removeAttribute('id'));return `<section class="print-sheet ${orientation} ${i===11?'references':i===2?'history':i===8?'landmarks':i===1?'framework':''}"><div class="print-head"><small>WASHINGTON, D.C. / READING THE CITY · ${String(i+1).padStart(2,'0')} / 12</small><h2>${c.title}</h2><p class="print-deck">${c.deck}</p></div><div class="print-layout"><div class="print-visual">${printVisual(c,i)}</div><div class="print-body">${clean.innerHTML}${takeaway(c.take)}${cite(...c.sources)}</div></div><div class="print-foot"><span>URBAN FIELDNOTES · KEVIN LYNCH’S FIVE ELEMENTS</span><span>${String(i+1).padStart(2,'0')}</span></div></section>`;}).join('');let style=$('#print-page-style');if(!style){style=document.createElement('style');style.id='print-page-style';document.head.append(style);}style.textContent=`@page {size:A4 ${orientation};margin:0;}`;document.body.dataset.orientation=orientation;$('#print-label').textContent='A4 '+orientation+' · 12 sheets';document.body.classList.add('print-preview');$('#print-toolbar').hidden=false;window.scrollTo(0,0);}
$$('[data-print]').forEach(b=>b.onclick=()=>{$('#print-dialog').close();buildPrint(b.dataset.print);});$('#return-web').onclick=()=>{document.body.classList.remove('print-preview');$('#print-toolbar').hidden=true;$('#print-edition').innerHTML='';$('#print-open').focus();};$('#print-now').onclick=()=>window.print();window.buildPrint=buildPrint;
